package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.*;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.*;
import static cn.sifangguan.hotelaios.finance.FinanceControlModels.*;

/** Full V107, actual application role and real source workflow; no inferred project/category identities. */
class FinanceProjectBudgetIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;
 static FinanceOperationsService ops;static FinanceService claims;static FinanceControlService control;static FinanceProjectDimensions projects;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");static final LocalDate DAY=LocalDate.of(2026,10,24);
 UUID hotel,company,owner,manager,finance,director,leader,cashier,category;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("107").load().migrate();named=new NamedParameterJdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));var database=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var mapper=new ObjectMapper().findAndRegisterModules();var audit=new AuditWriter(named,e->{});var accounting=new FinanceAccountingService(named,database,access,audit,mapper);ops=new FinanceOperationsService(named,database,access,mapper,audit,accounting);claims=new FinanceService(named,database,access,mapper,audit,accounting);control=new FinanceControlService(named,database,access,claims,ops,accounting);projects=new FinanceProjectDimensions(named,access);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}@AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();owner=user();manager=user();finance=user();director=user();leader=user();cashier=user();category=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'真实项目门店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'项目实际法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,payable_account,enabled) values(?,?,?,?,?,?,?,?,2,'应付款',true)",T,hotel,company,manager,finance,director,leader,cashier);as(owner,"finance.configure");call(()->claims.category(hotel,category,new FinanceModels.Category("真实随机ID类别","EXPENSE","","管理费用",true,-1,"PROJECT_COST")));}
 @Test void actualApprovedContractChoicesAndVersionFreezeAreNotGuessed(){UUID contract=approvedContract();as(owner,"finance.submit");var selected=call(()->projects.freeze(TenantContext.require(),hotel,company,new FinanceProjectDimensions.ProjectRef("CONTRACT",contract)));assertThat(selected).containsEntry("key","CONTRACT:"+contract).containsEntry("sourceVersion",5);UUID doc=draft("30",contract);assertThat(jdbc.queryForObject("select details->'projectSnapshot'->>'id' from fo_document where id=?",String.class,doc)).isEqualTo(contract.toString());call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select details->>'projectKey' from fo_document where id=?",String.class,doc)).isEqualTo("CONTRACT:"+contract);as(user(),"finance.submit");assertThat(((List<?>)call(()->projects.choices(TenantContext.require(),hotel,company)).get("items"))).isEmpty();assertThatThrownBy(()->call(()->projects.freeze(TenantContext.require(),hotel,company,new FinanceProjectDimensions.ProjectRef("CONTRACT",contract)))).hasMessageContaining("可见范围");}
 @Test void crossCompanyAndUnapprovedProjectAreRejectedWithoutChangingOriginalDraft(){UUID contract=approvedContract();as(owner,"finance.submit");assertThatThrownBy(()->call(()->projects.freeze(TenantContext.require(),hotel,UUID.randomUUID(),new FinanceProjectDimensions.ProjectRef("CONTRACT",contract)))).hasMessageContaining("主体不一致");UUID draftContract=contractDraft();assertThatThrownBy(()->draft("10",draftContract)).hasMessageContaining("未完成审批");assertThat(jdbc.queryForObject("select status from fo_document where id=?",String.class,draftContract)).isEqualTo("DRAFT");assertThatThrownBy(()->new FinanceProjectDimensions.ProjectRef("CONTRACT",null)).hasMessageContaining("任意编号");}
 @Test void projectSpecificBudgetOnlyConsumesItsRealProjectAndDoesNotDuplicateCost(){UUID first=approvedContract(),second=approvedContract();UUID policy=budget("BLOCK","50",first);as(owner,"finance.submit");UUID a=draft("40",first);call(()->ops.submit(a,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));UUID unrelated=draft("40",second);call(()->ops.submit(unrelated,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));UUID excess=draft("11",first);assertThatThrownBy(()->call(()->ops.submit(excess,new FinanceOperationsModels.Version(UUID.randomUUID(),0)))).hasMessageContaining("预算超额");assertThat(jdbc.queryForObject("select amount from fc_budget_usage where policy_id=? and source_id=?",BigDecimal.class,policy,a)).isEqualByComparingTo("40");assertThat(jdbc.queryForObject("select count(*) from fc_budget_usage where source_id=?",Integer.class,unrelated)).isZero();assertThat(jdbc.queryForObject("select count(*) from finance_expense_entry where hotel_id=?",Integer.class,hotel)).isZero();assertThat(jdbc.queryForObject("select project_key from fc_budget_usage where source_id=?",String.class,a)).isEqualTo("CONTRACT:"+first);}
 @Test void allProjectBudgetSeesMultipleProjectsAndWarnRetainsExactReservation(){UUID first=approvedContract(),second=approvedContract();UUID policy=budget("WARN","50",null);as(owner,"finance.submit");for(UUID project:List.of(first,second)){UUID d=draft("40",project);call(()->ops.submit(d,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));}assertThat(jdbc.queryForObject("select sum(amount) from fc_budget_usage where policy_id=?",BigDecimal.class,policy)).isEqualByComparingTo("80");assertThat(jdbc.queryForObject("select count(*) from fc_event where hotel_id=? and event='BUDGET_WARNING'",Integer.class,hotel)).isOne();assertThat(jdbc.queryForObject("select count(distinct project_key) from fc_budget_usage where policy_id=?",Integer.class,policy)).isOne();}
 @Test void trueCategoryIdAndCodeMustBothMatchAtIndependentPublish(){UUID id=UUID.randomUUID();as(owner,"finance.configure");call(()->control.savePolicy(new Policy(id,hotel,"BUDGET","BAD-"+id,"不能发布跨店类别",DAY.withDayOfMonth(1),null,Map.of("month","2026-10","amount","50","control","BLOCK","categoryCode","PROJECT_COST","categoryId",UUID.randomUUID(),"budgetKind","EXPENSE"))));as(director,"finance.configure");assertThatThrownBy(()->call(()->control.publishPolicy(id,new Version(0,"真实映射核对"),false))).hasMessageContaining("真实ID");assertThat(jdbc.queryForObject("select status from fc_policy where id=?",String.class,id)).isEqualTo("DRAFT");}
 @Test void historicalUnreviewedProjectIsNotAssumedOutsideSpecificBudgetButExplicitNoneCanProceed(){UUID project=approvedContract();budget("BLOCK","100",project);as(owner,"finance.submit");UUID source=draft("30",null);jdbc.update("update fo_document set details=details-'projectKind'-'projectId'-'projectKey'-'projectSnapshot' where id=? and status='DRAFT'",source);assertThatThrownBy(()->call(()->ops.submit(source,new FinanceOperationsModels.Version(UUID.randomUUID(),0)))).hasMessageContaining("尚未核实项目");assertThat(jdbc.queryForObject("select status from fo_document where id=?",String.class,source)).isEqualTo("DRAFT");UUID explicit=draft("30",null);call(()->ops.submit(explicit,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select count(*) from fc_budget_usage where source_id=?",Integer.class,explicit)).isZero();}
 @Test void unassignedDraftWithoutCompanyIsExplicitNotAConnectedProject(){as(owner,"finance.submit");var none=call(()->projects.freeze(TenantContext.require(),hotel,null,new FinanceProjectDimensions.ProjectRef("NONE",null)));assertThat(none).containsEntry("key","NONE").containsEntry("designation","EXPLICIT_NONE");assertThatThrownBy(()->call(()->projects.freeze(TenantContext.require(),hotel,null,new FinanceProjectDimensions.ProjectRef("CONTRACT",UUID.randomUUID())))).hasMessageContaining("法人主体");}
 private UUID budget(String controlMode,String amount,UUID project){UUID id=UUID.randomUUID();var spec=new LinkedHashMap<String,Object>(Map.of("month","2026-10","amount",amount,"control",controlMode,"categoryCode","PROJECT_COST","categoryId",category,"budgetKind","EXPENSE","projectKind",project==null?"ALL":"CONTRACT"));if(project!=null)spec.put("projectId",project);as(owner,"finance.configure");call(()->control.savePolicy(new Policy(id,hotel,"BUDGET","LIMIT-"+id,"真实独立预算",DAY.withDayOfMonth(1),null,spec)));as(director,"finance.configure");call(()->control.publishPolicy(id,new Version(0,"独立核对项目和真实类别"),false));return id;}
 private UUID draft(String amount,UUID project){var details=new LinkedHashMap<String,Object>(Map.of("treatment","EXPENSE","orderReference","真实订单","acceptanceReference","真实验收","invoiceReference","真实发票","mismatchNote",""));if(project!=null){details.put("projectKind","CONTRACT");details.put("projectId",project);}UUID request=UUID.randomUUID();call(()->ops.save(null,new FinanceOperationsModels.Document(request,0,hotel,"PAYABLE","实际项目支出",DAY,null,null,"MANUAL",null,"实际原件引用",null,details,List.of(new FinanceOperationsModels.Line("实际项目维修",BigDecimal.ONE,new BigDecimal(amount),"PROJECT_COST",null)))));return request;}
 private UUID contractDraft(){as(owner,"finance.submit");UUID request=UUID.randomUUID();call(()->ops.save(null,new FinanceOperationsModels.Document(request,0,hotel,"CONTRACT","真实已批项目锚点",DAY,null,null,"MANUAL",null,"实际合同原件",null,Map.of("contractNumber",request.toString(),"startDate","2026-10-01","endDate","2026-12-31","paymentPlan",List.of(Map.of("date","2026-10-24","amount","100","label","实际一期"))),List.of(new FinanceOperationsModels.Line("合同实际义务",BigDecimal.ONE,new BigDecimal("100"),"PROJECT_COST",null)))));return request;}
 private UUID approvedContract(){UUID doc=contractDraft();call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));int version=1;for(UUID reviewer:List.of(manager,finance,director,leader)){as(reviewer,"finance.review");int current=version++;call(()->ops.review(doc,new FinanceOperationsModels.Review(UUID.randomUUID(),current,"APPROVE","实际合同独立核对")));}return doc;}
 private UUID user(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'实际项目人员')",id,T,id.toString());return id;}
 private void as(UUID actor,String... permissions){TenantContext.set(new TenantPrincipal(T,actor,"PROJECT_TEST",Set.of("PROJECT_TEST"),Set.of(permissions),Set.of(hotel),Set.of(),false,UUID.randomUUID()));}
 private static <R> R call(Supplier<R> body){return tx.execute(status->{jdbc.execute("set local role hotel_ai_os_app");new TenantDatabaseContext(jdbc,true).apply(T);return body.get();});}
}
